+	AgentType      string   `json:"agent"`
+	Provider       string   `json:"provider"`
+	Model          string   `json:"model,omitempty"`
+	TokenHash      string   `json:"token_hash"`
+	MissionID      string   `json:"mission_id,omitempty"`
+	Branch         string   `json:"branch,omitempty"`
+	ChangedFiles   []string `json:"changed_files,omitempty"`
+	CheckpointID   string   `json:"checkpoint_id,omitempty"`
+	Blocker        string   `json:"blocker,omitempty"`
+	LastActivity   string   `json:"last_activity,omitempty"`
+	LastHeartbeat  string   `json:"last_heartbeat"`
+}
+
+type NetworkStore struct {
+	mu          sync.RWMutex
+	path        string
+	state       networkState
+	now         func() time.Time
+	eventID     uint64
+	subscribers map[string]map[chan TeamEvent]bool
+}
+
+func OpenNetworkStore(path string) (*NetworkStore, error) {
+	store := &NetworkStore{
+		path: path, now: time.Now,
+		state: networkState{SchemaVersion: NetworkSchemaVersion, Teams: map[string]*teamRecord{}},
+		subscribers: map[string]map[chan TeamEvent]bool{},
+	}
+	content, err := os.ReadFile(path)
+	if errors.Is(err, os.ErrNotExist) {
+		return store, nil
+	}
+	if err != nil {
+		return nil, fmt.Errorf("read network state: %w", err)
+	}
+	if len(content) > maxNetworkFileBytes {
+		return nil, fmt.Errorf("network state exceeds %d bytes", maxNetworkFileBytes)
+	}
+	if err := json.Unmarshal(content, &store.state); err != nil {
+		return nil, fmt.Errorf("decode network state: %w", err)
+	}
+	if store.state.SchemaVersion != NetworkSchemaVersion {
+		return nil, fmt.Errorf("unsupported network schema %q", store.state.SchemaVersion)
+	}
+	if store.state.Teams == nil {
+		store.state.Teams = map[string]*teamRecord{}
+	}
+	return store, nil
+}
+
+func (store *NetworkStore) CreateTeam(request CreateTeamRequest) (TeamCredentials, error) {
+	if err := validateText("team name", request.Name, 1, 100); err != nil { return TeamCredentials{}, err }
+	if err := validateText("leader name", request.LeaderName, 1, 100); err != nil { return TeamCredentials{}, err }
+	if err := validateText("objective", request.Objective, 0, 500); err != nil { return TeamCredentials{}, err }
+	if err := validateText("leader role", request.LeaderRole, 0, 100); err != nil { return TeamCredentials{}, err }
+	teamID, err := randomValue("team_", 12); if err != nil { return TeamCredentials{}, err }
+	memberID, err := randomValue("member_", 12); if err != nil { return TeamCredentials{}, err }
+	invite, err := randomValue("invite_", 12); if err != nil { return TeamCredentials{}, err }
+	admin, err := randomValue("admin_", 32); if err != nil { return TeamCredentials{}, err }
+	connector, err := randomValue("connector_", 32); if err != nil { return TeamCredentials{}, err }
+	store.mu.Lock()
+	defer store.mu.Unlock()
+	store.state.Teams[teamID] = &teamRecord{
+		ID: teamID, Name: strings.TrimSpace(request.Name), Objective: strings.TrimSpace(request.Objective),
+		InviteHash: tokenHash(invite), AdminHash: tokenHash(admin), CreatedAt: store.now().UTC().Format(time.RFC3339Nano),
+		Members: map[string]*networkMember{memberID: {ID: memberID, Name: strings.TrimSpace(request.LeaderName), Role: strings.TrimSpace(request.LeaderRole), ConnectorHash: tokenHash(connector)}},
+		Agents: map[string]*agentRecord{},
+	}
+	if err := store.persistLocked(); err != nil { delete(store.state.Teams, teamID); return TeamCredentials{}, err }
+	return TeamCredentials{TeamID: teamID, InviteCode: invite, AdminToken: admin, MemberID: memberID, ConnectorToken: connector}, nil
+}
+
+func (store *NetworkStore) JoinTeam(teamID string, request JoinTeamRequest) (JoinCredentials, error) {
+	if err := validateText("name", request.Name, 1, 100); err != nil { return JoinCredentials{}, err }
+	if err := validateText("role", request.Role, 0, 100); err != nil { return JoinCredentials{}, err }
+	store.mu.Lock()
+	defer store.mu.Unlock()
+	team, ok := store.state.Teams[teamID]
+	if !ok { return JoinCredentials{}, ErrTeamNotFound }
+	if !tokenMatches(request.InviteCode, team.InviteHash) { return JoinCredentials{}, ErrUnauthorized }
+	memberID, err := randomValue("member_", 12); if err != nil { return JoinCredentials{}, err }
+	connector, err := randomValue("connector_", 32); if err != nil { return JoinCredentials{}, err }
+	team.Members[memberID] = &networkMember{ID: memberID, Name: strings.TrimSpace(request.Name), Role: strings.TrimSpace(request.Role), ConnectorHash: tokenHash(connector)}
+	if err := store.persistLocked(); err != nil { delete(team.Members, memberID); return JoinCredentials{}, err }
+	return JoinCredentials{TeamID: teamID, MemberID: memberID, ConnectorToken: connector}, nil
